    "article": "Artigo 2",
    "title": "Constituição do Estado do Pará (CEPA/1989) - Artigo 2",
    "content": "São Poderes do Estado de Pará, independentes e harmônicos entre si, o Legislativo, o Executivo e o Judiciário. Parágrafo único. É vedado a qualquer dos Poderes delegar atribuições, e o cidadão investido na função de um deles não poderá exercer a de outro, salvo as exceções previstas nesta Constituição.",
