    "article": "Artigo 3",
    "title": "Constituição do Estado de Mato Grosso do Sul (CEMS/1989) - Artigo 3",
    "content": "São bens do Estado de Mato Grosso do Sul: I - as águas superficiais ou subterrâneas, fluentes, emergentes e em depósito, ressalvadas, neste caso, na forma da lei, as decorrentes de obras da União; II - as áreas, nas ilhas oceânicas e fluviais, que estiverem sob seu domínio; III - as terras devolutas não compreendidas entre as da União.",
