    "content": "A Segurança Pública no Estado de Piauí, dever do Estado, direito e responsabilidade de todos, é exercida para a preservação da ordem pública e da incolumidade das pessoas e do patrimônio, por meio dos seguintes órgãos: I - Polícia Civil; II - Polícia Militar; III - Corpo de Bombeiros Militar; IV - Polícia Penal Estadual.",
