    "title": "Constituição do Estado do Tocantins (CETO/1989) - Artigo 1",
    "content": "O Estado de Tocantins, integrante indissociável da República Federativa do Brasil, exerce em seu território todos os poderes que não lhe sejam vedados pela Constituição Federal, fundamentando sua autonomia na soberania popular, na dignidade da pessoa humana, nos valores sociais do trabalho e da livre iniciativa e no pluralismo político.",
